package main

import (
	"fmt"
	"strings"
)

func main() {
	s := "héllo"
	fmt.Println(len(s))
	for i, r := range s {
		if r == 'l' {
			fmt.Println(i)
			break
		}
	}
	fmt.Println(len([]rune(s)))

	var b strings.Builder
	for _, r := range s {
		if r != 'l' {
			b.WriteRune(r)
		}
	}
	fmt.Println(b.Len())
}

