package main

import "fmt"

type Config struct {
	Retries int
	Debug   bool
}

// applyDefaults mengisi nilai default ke Config milik pemanggil.
func applyDefaults(c *Config) {
	if c.Retries == 0 {
		c = &Config{Retries: 3, Debug: c.Debug}
	}
}

func main() {
	cfg := Config{Debug: true}
	applyDefaults(&cfg)
	fmt.Println(cfg.Retries, cfg.Debug) // harapan: 3 true
}
